<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Кому подчиняется военное представительство на предприятии?", "acceptedAnswer": {"@type": "Answer", "text": "Военные представительства и органы их контроля входят в состав Вооружённых Сил Российской Федерации. Руководство их деятельностью осуществляет Минобороны России через уполномоченные органы военного управления; предприятие, на территории которого размещено ВП, ему не руководит."}}, {"@type": "Question", "name": "Что делать, если военного представительства в организации нет?", "acceptedAnswer": {"@type": "Answer", "text": "Минобороны направляет в такую организацию своих представителей с теми же правами и обязанностями в части порученных работ. Кроме того, при отсутствии ВП организация обязана сама уведомлять государственных заказчиков о ходе выполнения контрактов."}}, {"@type": "Question", "name": "Обязательно ли заключение ВП о цене?", "acceptedAnswer": {"@type": "Answer", "text": "Оно выдаётся в процедурах ценового регулирования, прямо названных в форме приказа № 224: определение прогнозной цены единицы продукции потенциального единственного поставщика, определение цены контракта с единственным поставщиком и перевод других видов цен в фиксированную."}}, {"@type": "Question", "name": "Может ли ВП снизить цену, которую предприятие считает обоснованной?", "acceptedAnswer": {"@type": "Answer", "text": "Заключение фиксирует, какие экономические показатели и статьи затрат приняты, а какие отклонены, с указанием причин по каждой строке. Дальнейшее движение цены определяется процедурой ценового регулирования, а не самим заключением."}}, {"@type": "Question", "name": "Почему отклоняют накладные расходы?", "acceptedAnswer": {"@type": "Answer", "text": "Чаще всего — из-за несоответствия применённой базы распределения той, что закреплена в учётной политике организации на соответствующий год: форма заключения прямо привязывает базу распределения к учётной политике."}}, {"@type": "Question", "name": "В каких случаях ВП обязано остановить отгрузку?", "acceptedAnswer": {"@type": "Answer", "text": "Положение называет шесть оснований: невыполнение условий контракта и решений по качеству, отрицательные результаты испытаний, нарушение особо ответственных технологических процессов, выявление в эксплуатации дефектов, имеющихся в продукции в производстве, использование контрафактных и некондиционных комплектующих, нарушение требований технической защиты информации."}}, {"@type": "Question", "name": "Как возобновляется приёмка после приостановки?", "acceptedAnswer": {"@type": "Answer", "text": "После проведения организацией мероприятий по устранению выявленных недостатков и их причин, согласованных с государственным заказчиком. Начальник ВП письменно уведомляет о приостановке организацию, заказчика и контрольный орган в сфере гособоронзаказа."}}, {"@type": "Question", "name": "Кто платит за работу военного представительства?", "acceptedAnswer": {"@type": "Answer", "text": "В рамках гособоронзаказа отдельная плата предприятием не вносится. Норма отчисления 1,95 % установлена для продукции, поставляемой вне гособоронзаказа; по договорам, заключённым до 8 сентября 2021 года со сроком исполнения после этой даты, действует норма 1 %."}}, {"@type": "Question", "name": "Может ли ВП контролировать продукцию, которую оно не принимает?", "acceptedAnswer": {"@type": "Answer", "text": "Да, выборочно. Порядок такого контроля должен быть оговорён в государственном контракте. Кроме того, ВП вправе проводить выборочную проверку, разборку и испытания продукции по согласованию с руководителем организации."}}, {"@type": "Question", "name": "Обязано ли предприятие предоставлять помещения и оборудование?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Положение возлагает на руководителей организаций обеспечение ВП документацией, контрольно-измерительными приборами, инструментом, оснасткой и персоналом для испытаний, оборудованными служебными помещениями, услугами делопроизводства и средствами связи."}}, {"@type": "Question", "name": "Распространяются ли правила на представительства других ведомств?", "acceptedAnswer": {"@type": "Answer", "text": "Действие Положения распространено на военные представительства МЧС России, ФСБ России, Росгвардии и ФСО России, а также — с рядом изъятий — на представительства заказчика МВД России."}}, {"@type": "Question", "name": "Как связаны ВП и казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Напрямую — никак: это разные институты. Но они опираются на одни и те же учётные данные. Военный представитель оценивает затраты при формировании цены, казначейство — при санкционировании конкретного платежа с лицевого счёта."}}, {"@type": "Question", "name": "Что делать, если заключение задерживается?", "acceptedAnswer": {"@type": "Answer", "text": "Опираться на документально зафиксированную хронологию: дата поступления обосновывающих документов указывается в самом заключении. Положение отдельно закрепляет ответственность ВП за необоснованную задержку выдачи заключений по выполненным этапам аванпроектов и НИОКР."}}, {"@type": "Question", "name": "Можно ли согласовать вопросы с военным представителем неформально?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Выплата организациями каких-либо вознаграждений военным представителям и их получение прямо запрещены Положением, а взаимное вмешательство в служебную деятельность не допускается."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как подготовиться к получению заключения военного представительства о цене", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Определить процедуру и основание", "text": "Уточните, для чего нужно заключение: прогнозная цена, цена контракта с единственным поставщиком или перевод другого вида цены в фиксированную. От процедуры зависит комплект документов и содержание расчёта."}, {"@type": "HowToStep", "position": 2, "name": "Сверить учётную политику с фактическим расчётом", "text": "Базы распределения общепроизводственных, общехозяйственных, транспортно-заготовительных и коммерческих затрат должны соответствовать учётной политике на соответствующий год — форма заключения проверяет именно это."}, {"@type": "HowToStep", "position": 3, "name": "Собрать обосновывающие документы по перечню", "text": "Комплект определяется подпунктами «а» — «г», «ж», «з», «к» — «м» пункта 37 Положения, утверждённого постановлением № 1465. Недостающие подтверждения заранее превращаются в отклонённые статьи затрат."}, {"@type": "HowToStep", "position": 4, "name": "Подготовить расчётно-калькуляционные материалы", "text": "Статьи калькуляции — от 0100 до 1900 по приложению № 1 к порядку определения состава затрат (приказ Минпромторга России № 334). Разделите собственные и привнесённые затраты."}, {"@type": "HowToStep", "position": 5, "name": "Направить документы письмом и зафиксировать дату", "text": "Реквизиты письма и дата поступления документов указываются в самом заключении. Эта дата — точка отсчёта в любых последующих разговорах о сроках."}, {"@type": "HowToStep", "position": 6, "name": "Отработать запросы военного представительства", "text": "Дополнительные вопросы закрывайте документами, а не пояснительными записками: принимается то, что подтверждено."}, {"@type": "HowToStep", "position": 7, "name": "Разобрать полученное заключение по строкам", "text": "Причины отнесения затрат к необоснованным указываются по каждой статье и подстатье отдельно. Разделите отклонения на «нет документа» и «не та методика» — лечатся они по-разному."}, {"@type": "HowToStep", "position": 8, "name": "Зафиксировать выводы на следующий период", "text": "Методические расхождения устраняйте в учётной политике на будущий год и в регистрах раздельного учёта, а не задним числом в текущей калькуляции."}]}
</script>
